// Process incoming Prometheus/Alertmanager webhook
const alerts = $input.item.json.alerts || [];
const status = $input.item.json.status || 'unknown';
const groupLabels = $input.item.json.groupLabels || {};
const commonLabels = $input.item.json.commonLabels || {};

// Determine alert severity and category
let severity = 'info';
let category = 'general';
let emoji = '📊';

if (alerts.length > 0) {
  severity = alerts[0].labels?.severity || 'info';
  category = alerts[0].labels?.category || 'general';
}

// Set emoji based on severity and category
switch (severity) {
  case 'critical':
    emoji = '🚨';
    break;
  case 'warning':
    emoji = '⚠️';
    break;
  default:
    switch (category) {
      case 'infrastructure':
        emoji = '🏗️';
        break;
      case 'application':
        emoji = '🚀';
        break;
      case 'security':
        emoji = '🔒';
        break;
      case 'performance':
        emoji = '📈';
        break;
      case 'network':
        emoji = '🌐';
        break;
      case 'database':
        emoji = '🗄️';
        break;
      case 'monitoring':
        emoji = '📊';
        break;
      default:
        emoji = '🔔';
    }
}

// Format alert message
let message = `${emoji} **${severity.toUpperCase()} ALERT** - Agentic Platform\n\n`;
message += `**Alert:** ${groupLabels.alertname || 'Unknown'}\n`;
message += `**Status:** ${status}\n`;
message += `**Category:** ${category}\n`;
message += `**Environment:** ${commonLabels.environment || 'production'}\n\n`;

// Add individual alert details
for (const alert of alerts) {
  const alertName = alert.labels?.alertname || 'Unknown Alert';
  const instance = alert.labels?.instance || 'Unknown Instance';
  const job = alert.labels?.job || 'Unknown Job';
  const summary = alert.annotations?.summary || '';
  const description = alert.annotations?.description || '';
  const runbookUrl = alert.annotations?.runbook_url || '';

  message += `**${instance}** (${job})\n`;
  if (summary) message += `• ${summary}\n`;
  if (description) message += `• ${description}\n`;
  message += `• Started: ${new Date(alert.startsAt).toLocaleString()}\n`;
  if (alert.endsAt && alert.endsAt !== '0001-01-01T00:00:00Z') {
    message += `• Ended: ${new Date(alert.endsAt).toLocaleString()}\n`;
  }
  if (runbookUrl) message += `• [Runbook](${runbookUrl})\n`;
  message += '\n';
}

// Add dashboard links
message += '**Quick Links:**\n';
message += '• [📊 Monitoring Dashboard](https://consulting.sa/monitoring/)\n';
message += '• [🔍 Prometheus](https://consulting.sa/prometheus/)\n';
message += '• [🚨 Alertmanager](https://consulting.sa/alertmanager/)\n';
message += '• [📈 Grafana](https://consulting.sa/grafana/)\n\n';

// Add timestamp
message += `*Alert processed at ${new Date().toLocaleString()} UTC*`;

// Determine notification channels based on severity
const shouldNotifySlack = ['critical', 'warning'].includes(severity);
const shouldNotifyEmail = severity === 'critical';
const shouldNotifyTelegram = severity === 'critical';
const shouldNotifySMS = severity === 'critical' && category === 'infrastructure';

// Create structured output
return {
  message,
  severity,
  category,
  emoji,
  status,
  alertCount: alerts.length,
  alerts,
  groupLabels,
  commonLabels,
  shouldNotifySlack,
  shouldNotifyEmail,
  shouldNotifyTelegram,
  shouldNotifySMS,
  timestamp: new Date().toISOString(),
  dashboardUrl: 'https://consulting.sa/monitoring/',
  prometheusUrl: 'https://consulting.sa/prometheus/',
  alertmanagerUrl: 'https://consulting.sa/alertmanager/'
};

// Log alert to database/monitoring system
const alertData = {
  timestamp: $json.timestamp,
  severity: $json.severity,
  category: $json.category,
  alertName: $json.groupLabels?.alertname,
  status: $json.status,
  alertCount: $json.alertCount,
  environment: $json.commonLabels?.environment || 'production',
  processed: true
};

// Store in monitoring database or send to logging service
console.log('Alert processed:', JSON.stringify(alertData, null, 2));

return { alertData, processed: true };

